     1	using Microsoft.Xna.Framework;
     2	using ProjectTower.map;
     3	using SheetEdit.TextureSheet;
     4	
     5	namespace MapEdit.glows;
     6	
     7	public class Glow
     8	{
     9		private Vector2 loc;
    10	
    11		private float r;
    12	
    13		private float g;
    14	
    15		private float b;
    16	
    17		private float size;
    18	
    19		private int type;
    20	
    21		public const int TYPE_NORMAL = 0;
    22	
    23		public const int TYPE_WARM = 1;
    24	
    25		internal void Init(Vector2 loc, float r, float g, float b, float size, int type)
    26		{
    27			this.loc = loc;
    28			this.r = r;
    29			this.g = g;
    30			this.b = b;
    31			this.size = size;
    32			this.type = type;
    33		}
    34	
    35		internal void Draw(XTexture xt, int type)
    36		{
    37			int idx = 144;
    38			float num = 0.6f;
    39			int num2 = this.type;
    40			if (num2 != 0 && num2 == 1)
    41			{
    42				idx = 166;
    43				num = 0.8f;
    44				g = r * 0.9f;
    45				b = r * 0.9f;
    46			}
    47			xt.Draw(loc, idx, size * new Vector2(1f, 1f) * num, MapMgr.map.delta / 10f, r, g, b, 1f);
    48		}
    49	
    50		internal void DrawForLightMode(XTexture xt, int idx)
    51		{
    52			xt.Draw(loc, 144, size * new Vector2(1f, 1f) * 0.6f, MapMgr.map.delta / 10f, r, g, b, 1f);
    53		}
    54	}
    55	using Microsoft.Xna.Framework;
    56	using SheetEdit.TextureSheet;
    57	
    58	namespace MapEdit.glows;
    59	
    60	public class GlowList
    61	{
    62		private Glow[] glow;
    63	
    64		public int totalGlows;
    65	
    66		public int idx;
    67	
    68		public GlowList(int idx)
    69		{
    70			this.idx = idx;
    71			glow = new Glow[128];
    72			for (int i = 0; i < glow.Length; i++)
    73			{
    74				glow[i] = new Glow();
    75			}
    76		}
    77	
    78		public void AddGlow(Vector2 loc, float r, float g, float b, float size, int type)
    79		{
    80			_ = (int)loc.X;
    81			_ = 7;
    82			float num = size * 64f;
    83			float num2 = 200f;
    84			if (!(loc.X + num < 0f) && !(loc.Y + num < 0f) && !(loc.X - num > ScrollManager.screenSize.X) && !(loc.Y - num > ScrollManager.screenSize.Y))
    85			{
    86				float num3 = 1f;
    87				if (loc.X < 0f - num2)
    88				{
    89					num3 *= 1f - (0f - loc.X - num2) / num;
    90				}
    91				if (loc.Y < 0f - num2)
    92				{
    93					num3 *= 1f - (0f - loc.Y - num2) / num;
    94				}
    95				if (loc.X > ScrollManager.screenSize.X + num2)
    96				{
    97					num3 *= 1f - (loc.X - (ScrollManager.screenSize.X + num2)) / num;
    98				}
    99				if (loc.Y > ScrollManager.screenSize.Y + num2)
   100				{
   101					num3 *= 1f - (loc.Y - (ScrollManager.screenSize.Y + num2)) / num;
   102				}
   103				if (totalGlows < glow.Length)
   104				{
   105					glow[totalGlows].Init(loc, r, g, b, size * num3, type);
   106					totalGlows++;
   107				}
   108			}
   109		}
   110	
   111		public void Draw(XTexture xt)
   112		{
   113			for (int i = 0; i < totalGlows; i++)
   114			{
   115				glow[i].Draw(xt, idx);
   116			}
   117		}
   118	
   119		internal void Clear()
   120		{
   121			totalGlows = 0;
   122		}
   123	
   124		internal void DrawForLightMode(XTexture xt)
   125		{
   126			for (int i = 0; i < totalGlows; i++)
   127			{
   128				glow[i].DrawForLightMode(xt, idx);
   129			}
   130		}
   131	}
   132	using Microsoft.Xna.Framework;
   133	using Microsoft.Xna.Framework.Content;
   134	using Microsoft.Xna.Framework.Graphics;
   135	using ProjectTower;
   136	using SheetEdit.TextureSheet;
   137	
   138	namespace MapEdit.glows;
   139	
   140	public class GlowMgr
   141	{
   142		public const int GLOW_LIGHTMAP = 0;
   143	
   144		public const int GLOW_NORMAL = 1;
   145	
   146		public float alpha;
   147	
   148		public GlowList[] list = new GlowList[2]
   149		{
   150			new GlowList(0),
   151			new GlowList(1)
   152		};
   153	
   154		public Effect lightEffect;
   155	
   156		public Texture2D cloudsTex;
   157	
   158		public const int TOTAL_ADDS = 3;
   159	
   160		public float greenLanternFrame;
   161	
   162		public float greenLanternAlpha;
   163	
   164		private Vector2[] addVec;
   165	
   166		public float lightFac = 1f;
   167	
   168		public GlowMgr(ContentManager Content)
   169		{
   170			lightEffect = Content.Load<Effect>("fx/lightmap");
   171			cloudsTex = Content.Load<Texture2D>("gfx/waterstain");
   172			addVec = new Vector2[3];
   173		}
   174	
   175		public void Draw(XTexture xt)
   176		{
   177			list[1].Draw(xt);
   178		}
   179	
   180		internal void Add(int type, Vector2 loc, float r, float g, float b, float size, int glowType)
   181		{
   182			list[type].AddGlow(loc, r, g, b, size, glowType);
   183		}
   184	
   185		internal void Draw(XTexture xt, int idx)
   186		{
   187			list[idx].Draw(xt);
   188		}
   189	
   190		internal void Clear()
   191		{
   192			list[1].Clear();
   193		}
   194	
   195		internal void Prepare(XTexture xt, RenderTarget2D lightTarg)
   196		{
   197			GraphicsDevice graphicsDevice = lightTarg.GraphicsDevice;
   198			graphicsDevice.SetRenderTarget(lightTarg);
   199			graphicsDevice.Clear(new Color(1f, 1f, 1f, 1f));
   200			SpriteTools.BeginSubtractive();
   201			list[0].DrawForLightMode(xt);
   202			SpriteTools.End();
   203			list[0].Clear();
   204		}
   205	
   206		internal void Update()
   207		{
   208			if (greenLanternFrame > 0f)
   209			{
   210				greenLanternFrame -= Game1.frameTime;
   211				if (greenLanternAlpha < 1f)
   212				{
   213					greenLanternAlpha += Game1.frameTime;
   214					if (greenLanternAlpha > 1f)
   215					{
   216						greenLanternAlpha = 1f;
   217					}
   218				}
   219			}
   220			else if (greenLanternAlpha > 0f)
   221			{
   222				greenLanternAlpha -= Game1.frameTime;
