438				seq = seg.intFlag;
439				break;
440			case 30:
441				type = 4;
442				seq = seg.intFlag;
443				break;
444			case 15:
445				type = 2;
446				seq = seg.intFlag;
447				break;
448			}
449			srcScale = new Vector2(originalCell.srcRect.Width, originalCell.srcRect.Height);
450			srcScale /= 2f;
451			if (seg.strFlag != null)
452			{
453				string[] array = seg.strFlag.Split('\n');
454				for (int i = 0; i < array.Length; i++)
455				{
456					if (array[i].EndsWith("\r"))
457					{
458						array[i] = array[i].Substring(0, array[i].Length - 1);
459					}
460				}
461				for (int j = 0; j < array.Length; j++)
462				{
463					string[] array2 = array[j].Split(' ');
464					if (array2[0] == "key")
465					{
466						key = array2[1];
467					}
468				}
469			}
470			firable = true;
471		}
