473		public bool GetIntersect(Vector2 v)
474		{
475			_ = loc;
476			_ = srcScale;
477			_ = scale;
478			if (v.X > loc.X - srcScale.X * scale.X && v.X < loc.X + srcScale.X * scale.X && v.Y > loc.Y - srcScale.Y * scale.Y)
479			{
480				return v.Y < loc.Y + srcScale.Y * scale.Y;
481			}
482			return false;
483		}
