486		{
487			for (int i = 0; i < p.flags.Count; i++)
488			{
489				if (type != 6 && MapMgr.map.sequenceMgr.sequences[seq].name == p.flags[i])
490				{
491					firable = false;
492				}
493			}
494		}
495	
496		internal void Fire(Player p)
497		{
498			if (key != null)
499			{
500				if (!p.playerInv.HasKey(key))
501				{
502					p.prompts.MakeMessage(LocStrings.GetLocStr(1062));
503					return;
504				}
505				p.prompts.MakeMessage(LocStrings.GetLocStr(1063).Replace("[key]", p.playerInv.GetKeyName(key)));
506			}
507			firable = false;
508			MapMgr.map.sequenceMgr.sequences[seq].Activate();
509			PlayerMgr.SetMainPlayerFlag(MapMgr.map.sequenceMgr.sequences[seq].name);
510		}
